class VariableCharacteristics(OCPPModel):
    """Fixed read-only parameters of a variable.

    Attributes:
        unit: Unit of the variable. When the transmitted value has a unit, this field SHALL
            be included. Optional. At most 16 characters.
        data_type: Required. A ``Data``.
        min_limit: Minimum possible value of this variable. Optional.
        max_limit: Maximum possible value of this variable. When the datatype of this
            Variable is String, OptionList, SequenceList or MemberList, this field defines
            the maximum length of the (CSV) string. Optional.
        max_elements: *(2.1)* Maximum number of elements from _valuesList_ that are
            supported as _attributeValue_. Optional. At least 1.
        values_list: Mandatory when _dataType_ = OptionList, MemberList or SequenceList. In
            that case _valuesList_ specifies the allowed values for the type. The length of
            this field can be limited by DeviceDataCtrlr.ConfigurationValueSize. *
            OptionList: The (Actual) Variable value must be a single value from the reported
            (CSV) enumeration list. * MemberList: The (Actual) Variable value may be an
            (unordered) (sub-)set of the reported (CSV) valid values list. * SequenceList:
            The (Actual) Variable value may be an ordered (priority, etc) (sub-)set of the
            reported (CSV) valid values. This is a comma separated list. The Configuration
            Variable &lt;&lt;configkey-configuration-value-
            size,ConfigurationValueSize&gt;&gt; can be used to limit
            SetVariableData.attributeValue and VariableCharacteristics.valuesList. The max
            size of these values will always remain equal. Optional. At most 1000
            characters.
        supports_monitoring: Flag indicating if this variable supports monitoring. Required.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = VariableCharacteristics.model_validate({
        ...     "dataType": "string",
        ...     "supportsMonitoring": False,
        ... })
        >>> type(value).__name__
        'VariableCharacteristics'
    """

    unit: StrictStr | None = Field(default=None, max_length=16)
    data_type: Data
    min_limit: Number | None = Field(default=None)
    max_limit: Number | None = Field(default=None)
    max_elements: StrictInt | None = Field(default=None, ge=1)
    values_list: StrictStr | None = Field(default=None, max_length=1000)
    supports_monitoring: StrictBool
    custom_data: CustomData | None = Field(default=None)

    @model_validator(mode="after")
    def _check_rules(self) -> Self:
        lists = (
            Data.OPTION_LIST,
            Data.MEMBER_LIST,
            Data.SEQUENCE_LIST,
        )
        if not self.values_list and self.data_type in lists:
            raise needed_error("valuesList")
        return self


