class IdTokenInfo(OCPPModel):
    """Contains status information about an identifier. It is advised to not stop charging for
    a token that expires during charging, as ExpiryDate is only used for caching purposes.
    If ExpiryDate is not given, the status has no end date.

    Attributes:
        status: Required. A ``AuthorizationStatus``.
        cache_expiry_date_time: Date and Time after which the token must be considered
            invalid. Optional. A timestamp.
        charging_priority: Priority from a business point of view. Default priority is 0,
            The range is from -9 to 9. Higher values indicate a higher priority. The
            chargingPriority in
            &lt;&lt;transactioneventresponse,TransactionEventResponse&gt;&gt; overrules this
            one. Optional.
        group_id_token: Optional. A ``IdToken``.
        language1: Preferred user interface language of identifier user. Contains a language
            code as defined in &lt;&lt;ref-RFC5646,[RFC5646]&gt;&gt;. Optional. At most 8
            characters.
        language2: Second preferred user interface language of identifier user. Don't use
            when language1 is omitted, has to be different from language1. Contains a
            language code as defined in &lt;&lt;ref-RFC5646,[RFC5646]&gt;&gt;. Optional. At
            most 8 characters.
        evse_id: Only used when the IdToken is only valid for one or more specific EVSEs,
            not for the entire Charging Station. Optional. A list of int. At least 1 item.
        personal_message: Optional. A ``MessageContent``.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = IdTokenInfo.model_validate({"status": "Accepted"})
        >>> type(value).__name__
        'IdTokenInfo'
    """

    status: AuthorizationStatus
    cache_expiry_date_time: DateTime | None = Field(default=None)
    charging_priority: StrictInt | None = Field(default=None)
    group_id_token: IdToken | None = Field(default=None)
    language1: StrictStr | None = Field(default=None, max_length=8)
    language2: StrictStr | None = Field(default=None, max_length=8)
    evse_id: list[StrictInt] | None = Field(default=None, min_length=1)
    personal_message: MessageContent | None = Field(default=None)
    custom_data: CustomData | None = Field(default=None)


class TariffConditions(OCPPModel):
    """These conditions describe if and when a TariffEnergyType or TariffTimeType applies
    during a transaction. When more than one restriction is set, they are to be treated as a
    logical AND. All need to be valid before this price is active. For reverse energy flow
    (discharging) negative values of energy, power and current are used. NOTE: _minXXX_
    (where XXX = Kwh/A/Kw) must be read as "closest to zero", and _maxXXX_ as "furthest from
    zero". For example, a *charging* power range from 10 kW to 50 kWh is given by _minPower_
    = 10000 and _maxPower_ = 50000, and a *discharging* power range from -10 kW to -50 kW is
    given by _minPower_ = -10 and _maxPower_ = -50. NOTE: _startTimeOfDay_ and
    _endTimeOfDay_ are in local time, because it is the time in the tariff as it is shown to
    the EV driver at the Charging Station. A Charging Station will convert this to the
    internal time zone that it uses (which is recommended to be UTC, see section Generic
    chapter 3.1) when performing cost calculation.

    Attributes:
        start_time_of_day: Start time of day in local time. + Format as per RFC 3339: time-
            hour ":" time-minute + Must be in 24h format with leading zeros. Hour/Minute
            separator: ":" Regex: ([0-1][0-9]\\|2[0-3]):[0-5][0-9] Optional.
        end_time_of_day: End time of day in local time. Same syntax as _startTimeOfDay_. +
            If end time &lt; start time then the period wraps around to the next day. + To
            stop at end of the day use: 00:00. Optional.
        day_of_week: Day(s) of the week this is tariff applies. Optional. A list of
            DayOfWeek. At least 1 item. At most 7 items.
        valid_from_date: Start date in local time, for example: 2015-12-24. Valid from this
            day (inclusive). + Format as per RFC 3339: full-date + Regex:
            ([12][0-9]{3})-(0[1-9]\\|1[0-2])-(0[1-9]\\|[12][0-9]\\|3[01]) Optional.
        valid_to_date: End date in local time, for example: 2015-12-27. Valid until this day
            (exclusive). Same syntax as _validFromDate_. Optional.
        evse_kind: Optional. A ``EvseKind``.
        min_energy: Minimum consumed energy in Wh, for example 20000 Wh. Valid from this
            amount of energy (inclusive) being used. Optional.
        max_energy: Maximum consumed energy in Wh, for example 50000 Wh. Valid until this
            amount of energy (exclusive) being used. Optional.
        min_current: Sum of the minimum current (in Amperes) over all phases, for example 5
            A. When the EV is charging with more than, or equal to, the defined amount of
            current, this price is/becomes active. If the charging current is or becomes
            lower, this price is not or no longer valid and becomes inactive. + This is NOT
            about the minimum current over the entire transaction. Optional.
        max_current: Sum of the maximum current (in Amperes) over all phases, for example 20
            A. When the EV is charging with less than the defined amount of current, this
            price becomes/is active. If the charging current is or becomes higher, this
            price is not or no longer valid and becomes inactive. This is NOT about the
            maximum current over the entire transaction. Optional.
        min_power: Minimum power in W, for example 5000 W. When the EV is charging with more
            than, or equal to, the defined amount of power, this price is/becomes active. If
            the charging power is or becomes lower, this price is not or no longer valid and
            becomes inactive. This is NOT about the minimum power over the entire
            transaction. Optional.
        max_power: Maximum power in W, for example 20000 W. When the EV is charging with
            less than the defined amount of power, this price becomes/is active. If the
            charging power is or becomes higher, this price is not or no longer valid and
            becomes inactive. This is NOT about the maximum power over the entire
            transaction. Optional.
        min_time: Minimum duration in seconds the transaction (charging &amp; idle) MUST
            last (inclusive). When the duration of a transaction is longer than the defined
            value, this price is or becomes active. Before that moment, this price is not
            yet active. Optional.
        max_time: Maximum duration in seconds the transaction (charging &amp; idle) MUST
            last (exclusive). When the duration of a transaction is shorter than the defined
            value, this price is or becomes active. After that moment, this price is no
            longer active. Optional.
        min_charging_time: Minimum duration in seconds the charging MUST last (inclusive).
            When the duration of a charging is longer than the defined value, this price is
            or becomes active. Before that moment, this price is not yet active. Optional.
        max_charging_time: Maximum duration in seconds the charging MUST last (exclusive).
            When the duration of a charging is shorter than the defined value, this price is
            or becomes active. After that moment, this price is no longer active. Optional.
        min_idle_time: Minimum duration in seconds the idle period (i.e. not charging) MUST
            last (inclusive). When the duration of the idle time is longer than the defined
            value, this price is or becomes active. Before that moment, this price is not
            yet active. Optional.
        max_idle_time: Maximum duration in seconds the idle period (i.e. not charging) MUST
            last (exclusive). When the duration of idle time is shorter than the defined
            value, this price is or becomes active. After that moment, this price is no
            longer active. Optional.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = TariffConditions.model_validate({})
        >>> type(value).__name__
        'TariffConditions'
    """

    start_time_of_day: StrictStr | None = Field(default=None)
    end_time_of_day: StrictStr | None = Field(default=None)
    day_of_week: list[DayOfWeek] | None = Field(default=None, min_length=1, max_length=7)
    valid_from_date: StrictStr | None = Field(default=None)
    valid_to_date: StrictStr | None = Field(default=None)
    evse_kind: EvseKind | None = Field(default=None)
    min_energy: Number | None = Field(default=None)
    max_energy: Number | None = Field(default=None)
    min_current: Number | None = Field(default=None)
    max_current: Number | None = Field(default=None)
    min_power: Number | None = Field(default=None)
    max_power: Number | None = Field(default=None)
    min_time: StrictInt | None = Field(default=None)
    max_time: StrictInt | None = Field(default=None)
    min_charging_time: StrictInt | None = Field(default=None)
    max_charging_time: StrictInt | None = Field(default=None)
    min_idle_time: StrictInt | None = Field(default=None)
    max_idle_time: StrictInt | None = Field(default=None)
    custom_data: CustomData | None = Field(default=None)

    @model_validator(mode="after")
    def _check_rules(self) -> Self:
        for wire, value in (
            ("startTimeOfDay", self.start_time_of_day),
            ("endTimeOfDay", self.end_time_of_day),
        ):
            if value is not None and not time_of_day_ok(value):
                raise rule_error(wire, "must be HH:MM in 24h format with leading zeros")
        for wire, value in (
            ("validFromDate", self.valid_from_date),
            ("validToDate", self.valid_to_date),
        ):
            if value is not None and not full_date_ok(value):
                raise rule_error(wire, "must be a date written YYYY-MM-DD")
        return self


