class ChargingSchedulePeriod(OCPPModel):
    """Charging schedule period structure defines a time period in a charging schedule. It is
    used in: CompositeScheduleType and in ChargingScheduleType. When used in a
    NotifyEVChargingScheduleRequest only _startPeriod_, _limit_, _limit_L2_, _limit_L3_ are
    relevant.

    Attributes:
        start_period: Start of the period, in seconds from the start of schedule. The value
            of StartPeriod also defines the stop time of the previous period. Required.
        limit: Optional only when not required by the _operationMode_, as in
            CentralSetpoint, ExternalSetpoint, ExternalLimits, LocalFrequency,
            LocalLoadBalancing. + Charging rate limit during the schedule period, in the
            applicable _chargingRateUnit_. This SHOULD be a non-negative value; a negative
            value is only supported for backwards compatibility with older systems that use
            a negative value to specify a discharging limit. When using _chargingRateUnit_ =
            `W`, this field represents the sum of the power of all phases, unless values are
            provided for L2 and L3, in which case this field represents phase L1. Optional.
            At most one fractional digit.
        limit_l2: *(2.1)* Charging rate limit on phase L2 in the applicable
            _chargingRateUnit_. Optional.
        limit_l3: *(2.1)* Charging rate limit on phase L3 in the applicable
            _chargingRateUnit_. Optional.
        number_phases: The number of phases that can be used for charging. + For a DC EVSE
            this field should be omitted. + For an AC EVSE a default value of _numberPhases_
            = 3 will be assumed if the field is absent. Optional. At least 0. At most 3.
        phase_to_use: Values: 1..3, Used if numberPhases=1 and if the EVSE is capable of
            switching the phase connected to the EV, i.e. ACPhaseSwitchingSupported is
            defined and true. It's not allowed unless both conditions above are true. If
            both conditions are true, and phaseToUse is omitted, the Charging Station / EVSE
            will make the selection on its own. Optional. At least 1. At most 3.
        discharge_limit: *(2.1)* Limit in _chargingRateUnit_ that the EV is allowed to
            discharge with. Note, these are negative values in order to be consistent with
            _setpoint_, which can be positive and negative. + For AC this field represents
            the sum of all phases, unless values are provided for L2 and L3, in which case
            this field represents phase L1. Optional. At most 0.
        discharge_limit_l2: *(2.1)* Limit in _chargingRateUnit_ on phase L2 that the EV is
            allowed to discharge with. Optional. At most 0.
        discharge_limit_l3: *(2.1)* Limit in _chargingRateUnit_ on phase L3 that the EV is
            allowed to discharge with. Optional. At most 0.
        setpoint: *(2.1)* Setpoint in _chargingRateUnit_ that the EV should follow as close
            as possible. Use negative values for discharging. + When a limit and/or
            _dischargeLimit_ are given the overshoot when following _setpoint_ must remain
            within these values. This field represents the sum of all phases, unless values
            are provided for L2 and L3, in which case this field represents phase L1.
            Optional.
        setpoint_l2: *(2.1)* Setpoint in _chargingRateUnit_ that the EV should follow on
            phase L2 as close as possible. Optional.
        setpoint_l3: *(2.1)* Setpoint in _chargingRateUnit_ that the EV should follow on
            phase L3 as close as possible. Optional.
        setpoint_reactive: *(2.1)* Setpoint for reactive power (or current) in
            _chargingRateUnit_ that the EV should follow as closely as possible. Positive
            values for inductive, negative for capacitive reactive power or current. + This
            field represents the sum of all phases, unless values are provided for L2 and
            L3, in which case this field represents phase L1. Optional.
        setpoint_reactive_l2: *(2.1)* Setpoint for reactive power (or current) in
            _chargingRateUnit_ that the EV should follow on phase L2 as closely as possible.
            Optional.
        setpoint_reactive_l3: *(2.1)* Setpoint for reactive power (or current) in
            _chargingRateUnit_ that the EV should follow on phase L3 as closely as possible.
            Optional.
        preconditioning_request: *(2.1)* If true, the EV should attempt to keep the BMS
            preconditioned for this time interval. Optional.
        evse_sleep: *(2.1)* If true, the EVSE must turn off power electronics/modules
            associated with this transaction. Default value when absent is false. Optional.
        v2x_baseline: *(2.1)* Power value that, when present, is used as a baseline on top
            of which values from _v2xFreqWattCurve_ and _v2xSignalWattCurve_ are added.
            Optional.
        operation_mode: Optional. A ``OperationMode``.
        v2x_freq_watt_curve: Optional. A list of V2XFreqWattPoint. At least 1 item. At most
            20 items.
        v2x_signal_watt_curve: Optional. A list of V2XSignalWattPoint. At least 1 item. At
            most 20 items.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = ChargingSchedulePeriod.model_validate({"startPeriod": 1})
        >>> type(value).__name__
        'ChargingSchedulePeriod'
    """

    start_period: StrictInt
    limit: OneDecimal | None = Field(default=None)
    limit_l2: Number | None = Field(default=None, alias="limit_L2")
    limit_l3: Number | None = Field(default=None, alias="limit_L3")
    number_phases: StrictInt | None = Field(default=None, ge=0, le=3)
    phase_to_use: StrictInt | None = Field(default=None, ge=1, le=3)
    discharge_limit: Number | None = Field(default=None, le=0)
    discharge_limit_l2: Number | None = Field(default=None, alias="dischargeLimit_L2", le=0)
    discharge_limit_l3: Number | None = Field(default=None, alias="dischargeLimit_L3", le=0)
    setpoint: Number | None = Field(default=None)
    setpoint_l2: Number | None = Field(default=None, alias="setpoint_L2")
    setpoint_l3: Number | None = Field(default=None, alias="setpoint_L3")
    setpoint_reactive: Number | None = Field(default=None)
    setpoint_reactive_l2: Number | None = Field(default=None, alias="setpointReactive_L2")
    setpoint_reactive_l3: Number | None = Field(default=None, alias="setpointReactive_L3")
    preconditioning_request: StrictBool | None = Field(default=None)
    evse_sleep: StrictBool | None = Field(default=None)
    v2x_baseline: Number | None = Field(default=None, alias="v2xBaseline")
    operation_mode: OperationMode | None = Field(default=None)
    v2x_freq_watt_curve: list[V2XFreqWattPoint] | None = Field(
        default=None, alias="v2xFreqWattCurve", min_length=1, max_length=20
    )
    v2x_signal_watt_curve: list[V2XSignalWattPoint] | None = Field(
        default=None, alias="v2xSignalWattCurve", min_length=1, max_length=20
    )
    custom_data: CustomData | None = Field(default=None)

    @model_validator(mode="after")
    def _check_rules(self) -> Self:
        curve = self.v2x_freq_watt_curve
        mode = self.operation_mode
        if curve is None and mode == OperationMode.LOCAL_FREQUENCY:
            raise needed_error("v2xFreqWattCurve")
        if curve is not None and len(curve) < 2:
            raise rule_error("v2xFreqWattCurve", "must contain at least two coordinates")
        signal = self.v2x_signal_watt_curve
        if signal is not None and len(signal) < 2:
            raise rule_error("v2xSignalWattCurve", "must contain at least two coordinates")
        return self


