class AbsolutePriceSchedule(OCPPModel):
    """The AbsolutePriceScheduleType is modeled after the same type that is defined in ISO
    15118-20, such that if it is supplied by an EMSP as a signed EXI message, the conversion
    from EXI to JSON (in OCPP) and back to EXI (for ISO 15118-20) does not change the digest
    and therefore does not invalidate the signature. image::images/AbsolutePriceSchedule-
    Simple.png[]

    Attributes:
        time_anchor: Starting point of price schedule. Required. A timestamp.
        price_schedule_id: Unique ID of price schedule Required. At least 0.
        price_schedule_description: Description of the price schedule. Optional. At most 160
            characters.
        currency: Currency according to ISO 4217. Required. At most 3 characters.
        language: String that indicates what language is used for the human readable strings
            in the price schedule. Based on ISO 639. Required. At most 8 characters.
        price_algorithm: A string in URN notation which shall uniquely identify an algorithm
            that defines how to compute an energy fee sum for a specific power profile based
            on the EnergyFee information from the PriceRule elements. Required. At most 2000
            characters.
        minimum_cost: Optional. A ``RationalNumber``.
        maximum_cost: Optional. A ``RationalNumber``.
        price_rule_stacks: Required. A list of PriceRuleStack. At least 1 item. At most 1024
            items.
        tax_rules: Optional. A list of TaxRule. At least 1 item. At most 10 items.
        overstay_rule_list: Optional. A ``OverstayRuleList``.
        additional_selected_services: Optional. A list of AdditionalSelectedServices. At
            least 1 item. At most 5 items.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = AbsolutePriceSchedule.model_validate({
        ...     "timeAnchor": "2025-01-02T03:04:05Z",
        ...     "priceScheduleID": 1,
        ...     "currency": "x",
        ...     "language": "x",
        ...     "priceAlgorithm": "x",
        ...     "priceRuleStacks": [
        ...         {
        ...             "duration": 1,
        ...             "priceRule": [
        ...                 {
        ...                     "energyFee": {"exponent": 1, "value": 1},
        ...                     "powerRangeStart": {"exponent": 1, "value": 1},
        ...                 },
        ...             ],
        ...         },
        ...     ],
        ... })
        >>> type(value).__name__
        'AbsolutePriceSchedule'
    """

    time_anchor: DateTime
    price_schedule_id: StrictInt = Field(alias="priceScheduleID", ge=0)
    price_schedule_description: StrictStr | None = Field(default=None, max_length=160)
    currency: StrictStr = Field(min_length=1, max_length=3)
    language: StrictStr = Field(min_length=1, max_length=8)
    price_algorithm: StrictStr = Field(min_length=1, max_length=2000)
    minimum_cost: RationalNumber | None = Field(default=None)
    maximum_cost: RationalNumber | None = Field(default=None)
    price_rule_stacks: list[PriceRuleStack] = Field(min_length=1, max_length=1024)
    tax_rules: list[TaxRule] | None = Field(default=None, min_length=1, max_length=10)
    overstay_rule_list: OverstayRuleList | None = Field(default=None)
    additional_selected_services: list[AdditionalSelectedServices] | None = Field(
        default=None, min_length=1, max_length=5
    )
    custom_data: CustomData | None = Field(default=None)


