class ChargingSchedule(OCPPModel):
    """Charging schedule structure defines a list of charging periods, as used in:
    NotifyEVChargingScheduleRequest and ChargingProfileType. When used in a
    NotifyEVChargingScheduleRequest only _duration_ and _chargingSchedulePeriod_ are
    relevant and _chargingRateUnit_ must be 'W'. + An ISO 15118-20 session may provide
    either an _absolutePriceSchedule_ or a _priceLevelSchedule_. An ISO 15118-2 session can
    only provide a_salesTariff_ element. The field _digestValue_ is used when price schedule
    or sales tariff are signed. image::images/ChargingSchedule-Simple.png[]

    Attributes:
        id: Required.
        limit_at_so_c: Optional. A ``LimitAtSoC``.
        start_schedule: Starting point of an absolute schedule or recurring schedule.
            Optional. A timestamp.
        duration: Duration of the charging schedule in seconds. If the duration is left
            empty, the last period will continue indefinitely or until end of the
            transaction in case startSchedule is absent. Optional.
        charging_rate_unit: Required. A ``ChargingRateUnit``.
        min_charging_rate: Minimum charging rate supported by the EV. The unit of measure is
            defined by the chargingRateUnit. This parameter is intended to be used by a
            local smart charging algorithm to optimize the power allocation for in the case
            a charging process is inefficient at lower charging rates. Optional.
        power_tolerance: *(2.1)* Power tolerance when following EVPowerProfile. Optional.
        signature_id: *(2.1)* Id of this element for referencing in a signature. Optional.
            At least 0.
        digest_value: *(2.1)* Base64 encoded hash (SHA256 for ISO 15118-2, SHA512 for ISO
            15118-20) of the EXI price schedule element. Used in signature. Optional. At
            most 88 characters.
        use_local_time: *(2.1)* Defaults to false. When true, disregard time zone offset in
            dateTime fields of _ChargingScheduleType_ and use unqualified local time at
            Charging Station instead. This allows the same `Absolute` or `Recurring`
            charging profile to be used in both summer and winter time. Optional.
        charging_schedule_period: Required. A list of ChargingSchedulePeriod. At least 1
            item. At most 1024 items.
        randomized_delay: *(2.1)* Defaults to 0. When _randomizedDelay_ not equals zero,
            then the start of each
            &lt;&lt;cmn_chargingscheduleperiodtype,ChargingSchedulePeriodType&gt;&gt; is
            delayed by a randomly chosen number of seconds between 0 and _randomizedDelay_.
            Only allowed for TxProfile and TxDefaultProfile. Optional. At least 0.
        sales_tariff: Optional. A ``SalesTariff``.
        absolute_price_schedule: Optional. A ``AbsolutePriceSchedule``.
        price_level_schedule: Optional. A ``PriceLevelSchedule``.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = ChargingSchedule.model_validate({
        ...     "id": 1,
        ...     "chargingRateUnit": "W",
        ...     "chargingSchedulePeriod": [{"startPeriod": 1}],
        ... })
        >>> type(value).__name__
        'ChargingSchedule'
    """

    id: StrictInt
    limit_at_so_c: LimitAtSoC | None = Field(default=None)
    start_schedule: DateTime | None = Field(default=None)
    duration: StrictInt | None = Field(default=None)
    charging_rate_unit: ChargingRateUnit
    min_charging_rate: Number | None = Field(default=None)
    power_tolerance: Number | None = Field(default=None)
    signature_id: StrictInt | None = Field(default=None, ge=0)
    digest_value: StrictStr | None = Field(default=None, max_length=88)
    use_local_time: StrictBool | None = Field(default=None)
    charging_schedule_period: list[ChargingSchedulePeriod] = Field(min_length=1, max_length=1024)
    randomized_delay: StrictInt | None = Field(default=None, ge=0)
    sales_tariff: SalesTariff | None = Field(default=None)
    absolute_price_schedule: AbsolutePriceSchedule | None = Field(default=None)
    price_level_schedule: PriceLevelSchedule | None = Field(default=None)
    custom_data: CustomData | None = Field(default=None)


class ChargingProfile(OCPPModel):
    """A ChargingProfile consists of 1 to 3 ChargingSchedules with a list of
    ChargingSchedulePeriods, describing the amount of power or current that can be delivered
    per time interval. image::images/ChargingProfile-Simple.png[]

    Attributes:
        id: Id of ChargingProfile. Unique within charging station. Id can have a negative
            value. This is useful to distinguish charging profiles from an external actor
            (external constraints) from charging profiles received from CSMS. Required.
        stack_level: Value determining level in hierarchy stack of profiles. Higher values
            have precedence over lower values. Lowest level is 0. Required. At least 0.
        charging_profile_purpose: Required. A ``ChargingProfilePurpose``.
        charging_profile_kind: Required. A ``ChargingProfileKind``.
        recurrency_kind: Optional. A ``RecurrencyKind``.
        valid_from: Point in time at which the profile starts to be valid. If absent, the
            profile is valid as soon as it is received by the Charging Station. Optional. A
            timestamp.
        valid_to: Point in time at which the profile stops to be valid. If absent, the
            profile is valid until it is replaced by another profile. Optional. A timestamp.
        transaction_id: SHALL only be included if ChargingProfilePurpose is set to TxProfile
            in a SetChargingProfileRequest. The transactionId is used to match the profile
            to a specific transaction. Optional. At most 36 characters.
        max_offline_duration: *(2.1)* Period in seconds that this charging profile remains
            valid after the Charging Station has gone offline. After this period the
            charging profile becomes invalid for as long as it is offline and the Charging
            Station reverts back to a valid profile with a lower stack level. If
            _invalidAfterOfflineDuration_ is true, then this charging profile will become
            permanently invalid. A value of 0 means that the charging profile is immediately
            invalid while offline. When the field is absent, then no timeout applies and the
            charging profile remains valid when offline. Optional.
        charging_schedule: Required. A list of ChargingSchedule. At least 1 item. At most 3
            items.
        invalid_after_offline_duration: *(2.1)* When set to true this charging profile will
            not be valid anymore after being offline for more than _maxOfflineDuration_. +
            When absent defaults to false. Optional.
        dyn_update_interval: *(2.1)* Interval in seconds after receipt of last update, when
            to request a profile update by sending a PullDynamicScheduleUpdateRequest
            message. A value of 0 or no value means that no update interval applies. + Only
            relevant in a dynamic charging profile. Optional.
        dyn_update_time: *(2.1)* Time at which limits or setpoints in this charging profile
            were last updated by a PullDynamicScheduleUpdateRequest or
            UpdateDynamicScheduleRequest or by an external actor. + Only relevant in a
            dynamic charging profile. Optional. A timestamp.
        price_schedule_signature: *(2.1)* ISO 15118-20 signature for all price schedules in
            _chargingSchedules_. + Note: for 256-bit elliptic curves (like secp256k1) the
            ECDSA signature is 512 bits (64 bytes) and for 521-bit curves (like secp521r1)
            the signature is 1042 bits. This equals 131 bytes, which can be encoded as
            base64 in 176 bytes. Optional. At most 256 characters.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = ChargingProfile.model_validate({
        ...     "id": 1,
        ...     "stackLevel": 1,
        ...     "chargingProfilePurpose": "ChargingStationExternalConstraints",
        ...     "chargingProfileKind": "Absolute",
        ...     "chargingSchedule": [
        ...         {
        ...             "id": 1,
        ...             "chargingRateUnit": "W",
        ...             "chargingSchedulePeriod": [{"startPeriod": 1}],
        ...         },
        ...     ],
        ... })
        >>> type(value).__name__
        'ChargingProfile'
    """

    id: StrictInt
    stack_level: StrictInt = Field(ge=0)
    charging_profile_purpose: ChargingProfilePurpose
    charging_profile_kind: ChargingProfileKind
    recurrency_kind: RecurrencyKind | None = Field(default=None)
    valid_from: DateTime | None = Field(default=None)
    valid_to: DateTime | None = Field(default=None)
    transaction_id: StrictStr | None = Field(default=None, max_length=36)
    max_offline_duration: StrictInt | None = Field(default=None)
    charging_schedule: list[ChargingSchedule] = Field(min_length=1, max_length=3)
    invalid_after_offline_duration: StrictBool | None = Field(default=None)
    dyn_update_interval: StrictInt | None = Field(default=None)
    dyn_update_time: DateTime | None = Field(default=None)
    price_schedule_signature: StrictStr | None = Field(default=None, max_length=256)
    custom_data: CustomData | None = Field(default=None)

    @model_validator(mode="after")
    def _check_rules(self) -> Self:
        if (
            self.transaction_id
            and self.charging_profile_purpose != ChargingProfilePurpose.TX_PROFILE
        ):
            raise rule_error(
                "transactionId", "only allowed when chargingProfilePurpose is TxProfile"
            )

        tx_purposes = (ChargingProfilePurpose.TX_PROFILE, ChargingProfilePurpose.TX_DEFAULT_PROFILE)
        for index, schedule in enumerate(self.charging_schedule):
            if schedule.randomized_delay and self.charging_profile_purpose not in tx_purposes:
                raise rule_error(
                    f"chargingSchedule.{index}.randomizedDelay",
                    "only allowed for TxProfile and TxDefaultProfile",
                )
        return self


