class ChargingProfileCriterion(OCPPModel):
    """A ChargingProfileCriterionType is a filter for charging profiles to be selected by a
    GetChargingProfilesRequest.

    Attributes:
        charging_profile_purpose: Optional. A ``ChargingProfilePurpose``.
        stack_level: Value determining level in hierarchy stack of profiles. Higher values
            have precedence over lower values. Lowest level is 0. Optional. At least 0.
        charging_profile_id: List of all the chargingProfileIds requested. Any
            ChargingProfile that matches one of these profiles will be reported. If omitted,
            the Charging Station SHALL not filter on chargingProfileId. This field SHALL NOT
            contain more ids than set in &lt;&lt;configkey-charging-profile-
            entries,ChargingProfileEntries.maxLimit&gt;&gt; Optional. A list of int. At
            least 1 item.
        charging_limit_source: For which charging limit sources, charging profiles SHALL be
            reported. If omitted, the Charging Station SHALL not filter on
            chargingLimitSource. Values defined in Appendix as
            ChargingLimitSourceEnumStringType. Optional. A list of str. At least 1 item. At
            most 4 items.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = ChargingProfileCriterion.model_validate({})
        >>> type(value).__name__
        'ChargingProfileCriterion'
    """

    charging_profile_purpose: ChargingProfilePurpose | None = Field(default=None)
    stack_level: StrictInt | None = Field(default=None, ge=0)
    charging_profile_id: list[StrictInt] | None = Field(default=None, min_length=1)
    charging_limit_source: list[Annotated[StrictStr, StringConstraints(max_length=20)]] | None = (
        Field(default=None, min_length=1, max_length=4)
    )
    custom_data: CustomData | None = Field(default=None)


