class VoltageParams(OCPPModel):
    """The VoltageParams datatype.

    Attributes:
        hv10_min_mean_value: EN 50549-1 chapter 4.9.3.4 Voltage threshold for the 10 min
            time window mean value monitoring. The 10 min mean is recalculated up to every 3
            s. If the present voltage is above this threshold for more than the time defined
            by _hv10MinMeanValue_, the EV must trip. This value is mandatory if
            _hv10MinMeanTripDelay_ is set. Optional.
        hv10_min_mean_trip_delay: Time for which the voltage is allowed to stay above the 10
            min mean value. After this time, the EV must trip. This value is mandatory if
            OverVoltageMeanValue10min is set. Optional.
        power_during_cessation: Optional. A ``PowerDuringCessation``.
        custom_data: Optional. A ``CustomData``.

    Example:
        >>> value = VoltageParams.model_validate({})
        >>> type(value).__name__
        'VoltageParams'
    """

    hv10_min_mean_value: Number | None = Field(default=None)
    hv10_min_mean_trip_delay: Number | None = Field(default=None)
    power_during_cessation: PowerDuringCessation | None = Field(default=None)
    custom_data: CustomData | None = Field(default=None)

    @model_validator(mode="after")
    def _check_rules(self) -> Self:
        if self.hv10_min_mean_trip_delay is not None and self.hv10_min_mean_value is None:
            raise needed_error("hv10MinMeanValue")
        if self.hv10_min_mean_value is not None and self.hv10_min_mean_trip_delay is None:
            raise needed_error("hv10MinMeanTripDelay")
        return self


